// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // setup: no call needed
        // call transfer with empty tos and v arrays
        address[] memory tos = new address[](0);
        uint[] memory v = new uint[](0);
        bool ok;
        try c.transfer(address(0), address(0), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }
        // the reference reverts (ok=false), the mutant returns false (ok=true)
        // we assert the reference behavior: ok is false
        assertTrue(!ok);
    }
}

