pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple token that tracks transferFrom calls
        Token t = new Token();
        address[] memory tos = new address[](1);
        tos[0] = address(0x123);
        uint[] memory vals = new uint[](1);
        vals[0] = 100;
        address caller = address(0x456);
        vm.prank(caller);
        c.transfer(caller, address(t), tos, vals);
        // The reference contract calls t.transferFrom, which increments t.called()
        // The buggy contract does nothing, so t.called() stays false
        assertTrue(t.called());
    }
}

contract Token {
    bool public called;
    function transferFrom(address, address, uint256) external returns (bool) {
        called = true;
        return true;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a mock ERC20-like contract that logs transfers
        MockToken token = new MockToken();
        address from = address(0x1);
        address[] memory tos = new address[](1);
        tos[0] = address(0x2);
        uint[] memory amounts = new uint[](1);
        amounts[0] = 100;
        // Call transfer: reference calls token correctly, buggy calls itself
        c.transfer(from, address(token), tos, amounts);
        // In the reference, token.transferFrom would be called, increasing token's totalSupply
        // In the buggy, address(this) is called but C has no transferFrom, so nothing happens
        assertTrue(token.totalSupply() == 100);
    }
}

contract MockToken {
    uint256 public totalSupply;
    function transferFrom(address, address, uint256 amount) external returns (bool) {
        totalSupply += amount;
        return true;
    }
}
